using System;using System.Linq;using System.Reflection;using UnityEngine;
public static class VerifyEmptyCargoPickup{public static object Main(){int passed=0;var flags=BindingFlags.Instance|BindingFlags.NonPublic;foreach(var prefab in Resources.LoadAll<GameObject>("Vehicles")){var v=UnityEngine.Object.Instantiate(prefab,new Vector3(19000+passed*20,1000,18000),Quaternion.identity);GameObject actor=null,wall=null,bag=null;try{var rig=v.GetComponent<BicycleController>();if(rig==null)continue;rig.Initialize();var slot=rig.cargoSlots?.FirstOrDefault();if(slot==null)continue;bag=UnityEngine.Object.Instantiate(UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Gameplay/Containers/FreeBag.prefab"),slot);var c=bag.GetComponent<GrainContainer>();c.RefreshFillPresentation();VehicleCargoRack.SeatBase(bag.transform,slot);actor=new GameObject("Temporary cargo test actor");var cam=actor.AddComponent<Camera>();cam.enabled=false;actor.transform.position=c.WorldBounds.center+Vector3.up*2;actor.transform.rotation=Quaternion.LookRotation(Vector3.down,Vector3.forward);var bags=actor.AddComponent<BagInteraction>();var anchor=new GameObject("Carry anchor").transform;anchor.SetParent(actor.transform,false);typeof(BagInteraction).GetField("viewCamera",flags).SetValue(bags,cam);typeof(BagInteraction).GetField("carryAnchor",flags).SetValue(bags,anchor);var interactor=actor.AddComponent<PlayerInteractor>();Physics.SyncTransforms();var find=typeof(PlayerInteractor).GetMethod("FindTarget",flags);if((GrainContainer)(find.Invoke(interactor,null) as GrainContainer)!=c)throw new Exception(prefab.name+": cargo not targeted");wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=actor.transform.position+Vector3.down*.5f;wall.transform.localScale=new Vector3(2,.1f,2);Physics.SyncTransforms();if((find.Invoke(interactor,null) as GrainContainer)==c)throw new Exception("Pickup through wall");UnityEngine.Object.DestroyImmediate(wall);wall=null;Physics.SyncTransforms();passed++;}finally{if(wall!=null)UnityEngine.Object.DestroyImmediate(wall);if(actor!=null)UnityEngine.Object.DestroyImmediate(actor);if(bag!=null)UnityEngine.Object.DestroyImmediate(bag);UnityEngine.Object.DestroyImmediate(v);}}return "PASS: "+passed+" vehicle prefabs: empty bag selected, wall blocks selection, bag is carryable";}}



